# The tool descriptions, from the blockquote above each schema in SPEC.md 6.4.
# Hard line wrapping is undone; no word is changed.

TOOL_DESCRIPTIONS: dict[str, str] = {
    "x80_profiles": (
        "List the machine profiles this installation can actually run: backend, tier, "
        "capabilities, required disk images and whether they are present. **Call this "
        "first.** Capabilities differ enormously between backends, and a profile with a "
        "missing image or a ROM/disk version mismatch will fail `x80_open`."
    ),
    "x80_cpm_run": (
        "Run one CP/M package to completion in a fresh sandbox and return its console "
        "output, a manifest of the files it created, a termination reason, and your "
        "assertions. **This tool deliberately has no `exit_code` field**, because no "
        "CP/M backend has one: CP/M has no exit-status concept, cpmemu exit(0)s on "
        "every path including its runaway watchdog, romwbw_emu always returns 0, and a "
        "run that extracted 1 of 23 files and printed \"Error\" still exited 0 "
        "(measured). Success must be asserted from stdout plus the file manifest."
    ),
    "x80_dos_run": (
        "Run one DOS package to completion in a fresh sandbox. Unlike `x80_cpm_run` "
        "this **does** have a meaningful exit code \u2014 dosiz propagates the DOS AH=4Ch AL "
        "value (measured: rc 7) \u2014 but rc 1 is ambiguous between \"the guest exited 1\" "
        "and \"dosiz failed to load the program\", so `exit_code_meaning` disambiguates "
        "it from stderr."
    ),
    "x80_diff_run": (
        "Run the same inputs through a guest program and a host reference "
        "implementation and compare the outputs byte for byte under a **declared** "
        "normalization. Built for the case 80un proves: the same algorithm shipped as a "
        "CP/M .COM and as Python."
    ),
    "x80_files": (
        "Move files between the host and a guest, list what the guest can see, show "
        "what it has open right now, and answer \"where *would* `A:FOO.TXT` come from?\" "
        "without running anything. The direction is in the op name, not in a flag, "
        "because the single most common agent failure in this domain is editing a host "
        "copy of a file instead of the one the guest can see."
    ),
    "x80_probe": (
        "Run a package on the cheapest profile and report what operating system it "
        "actually needs, from the syscalls it made \u2014 evidence instead of a screen read. "
        "Returns a literal next call to make."
    ),
    "x80_images": (
        "Download and verify disk images from the pinned `romwbw_disks` catalog. Every "
        "other tool in this server is `openWorldHint:false`. **Never called "
        "implicitly** \u2014 no tool call may trigger a download."
    ),
}


