# Annotations -- SPEC.md 6.2, the table at lines 743-767, transcribed.
#
# "The defaults bite hard (destructiveHint true, openWorldHint true), so this
# table is not optional decoration" (6.2). Every tool is openWorldHint:false
# except x80_images, the only tool that touches the network.
#
# Rows for phase 2/3/4/5 tools are carried here too, so that when those tools
# are registered nobody re-derives the row from memory. Registering a tool
# whose name is missing from this table is a KeyError, by design.
# --------------------------------------------------------------------------

def _ann(read_only: bool, destructive: bool, idempotent: bool, open_world: bool) -> ToolAnnotations:
    return ToolAnnotations(
        readOnlyHint=read_only,
        destructiveHint=destructive,
        idempotentHint=idempotent,
        openWorldHint=open_world,
    )


